; NR43 values for the ch4 note/noise index (music, and SFX engine A in 15-bit LFSR mode).
NoiseTable::
	db $DF, $DE, $DD, $DC, $CF, $CE, $CD, $CC, $BF, $BE, $BD, $BC  ; 0-11
	db $AF, $AE, $AD, $AC, $9F, $9E, $9D, $9C, $8F, $8E, $8D, $8C  ; 12-23
	db $7F, $7E, $7D, $7C, $6F, $6E, $6D, $6C, $5F, $5E, $5D, $5C  ; 24-35
	db $4F, $4E, $4D, $4C, $3F, $3E, $3D, $3C, $2F, $2E, $2D, $2C  ; 36-47
	db $1F, $1E, $1D, $1C, $0F, $0E, $0D, $0C, $0B, $0A, $09, $08  ; 48-59

; Same with the 7-bit LFSR bit set (SFX engine A after SFX4_LFSR7).
NoiseTable7::
	db $D7, $D6, $D5, $D4, $C7, $C6, $C5, $C4, $B7, $B6, $B5, $B4  ; 0-11
	db $A7, $A6, $A5, $A4, $97, $96, $95, $94, $87, $86, $85, $84  ; 12-23
	db $77, $76, $75, $74, $67, $66, $65, $64, $57, $56, $55, $54  ; 24-35
	db $47, $46, $45, $44, $37, $36, $35, $34, $27, $26, $25, $24  ; 36-47
	db $17, $16, $15, $14, $07, $06, $05, $04, $03, $02, $01, $00  ; 48-59

; Pcm_Play: play bc bytes of 2-bit PCM from e:hl through ch3, blocking. The wave RAM is filled
; with $FF, so NR32 (output level) is the sample value. Each byte holds two samples:
; bits 5-4 level, bits 7-6 extra hold; bits 1-0 level, bits 3-2 extra hold.
; On CGB (hConsoleType = $11) every delay is done twice.
Pcm_Play::
	ldh a, [hROMBank]
	push af
	ld a, e
	ld [rROMB0], a
	ldh [hROMBank], a
	push hl
	push bc
	ld hl, _AUD3WAVERAM
	ld b, $10
	ld a, $FF
.l1A37
	ld [hl+], a
	dec b
	jr nz, .l1A37
	ld a, $80
	ldh [rNR30], a
	ld a, $20
	ldh [rNR32], a
	ld a, $FF
	ldh [rNR33], a
	ld a, $80
	ldh [rNR34], a
	pop bc
	pop hl
	ldh a, [hConsoleType]
	ld e, a
	ld a, $11
	sub e
	ld e, a
.l1A54
	inc e
	dec e
	call z, Pcm_Delay
	ld a, [hl]
	and $30
	sla a
	ldh [rNR32], a
	ld a, [hl]
	and $C0
	swap a
	srl a
	srl a
	inc a
	dec a
	jr z, .l1A78
.l1A6D
	inc e
	dec e
	call z, Pcm_Delay
	call Pcm_Delay
	dec a
	jr nz, .l1A6D
.l1A78
	inc e
	dec e
	call z, Pcm_Delay
	ld a, [hl]
	and $03
	sla a
	swap a
	ldh [rNR32], a
	ld a, [hl+]
	srl a
	srl a
	and $03
	jr z, .l1A9A
.l1A8F
	inc e
	dec e
	call z, Pcm_Delay
	call Pcm_Delay
	dec a
	jr nz, .l1A8F
.l1A9A
	dec bc
	ld a, c
	or b
	jr nz, .l1A54
	pop af
	ld [rROMB0], a
	ldh [hROMBank], a
	ret
Pcm_Delay::
	inc e
	dec e
	jr nz, .l1AB2
	inc d
	dec d
	jr nz, .l1AB4
	nop
	nop
	nop
	nop
.l1AB2
	nop
	nop
.l1AB4
	nop
	nop
	nop
	nop
	nop
	ret

; Sound_PlayPCM: a = sample 0-3 (PcmTable). Ignored while wSfxDisable is set.
Sound_PlayPCM::
	ld e, a
	add a, a
	add a, a
	add a, e
	ld e, a
	push de
	ld d, $00
	ld hl, $1ADE
	add hl, de
	pop de
	ld a, [hl-]
	ld b, a
	ld a, [hl-]
	ld c, a
	ld a, [hl-]
	ld e, a
	ld a, [hl-]
	ld l, [hl]
	ld h, a
	ld a, [wSfxDisable]
	and a
	jr nz, .l1AD9
	call Pcm_Play
.l1AD9
	ret

; PCM samples: address, bank, length in bytes.
PcmTable::
	PCM_ENTRY PcmSample0, PCM0_LEN
	PCM_ENTRY PcmSample1, PCM1_LEN
	PCM_ENTRY PcmSample2, PCM2_LEN
	PCM_ENTRY PcmSample3, PCM3_LEN

; SfxB_FarUpdate: run engine B (bank $7F); e = number of active engine B channels.
SfxB_FarUpdate::
	ldh a, [hROMBank]
	push af
	ld a, $7F
	ldh [hROMBank], a
	ld [rROMB0], a
	call $4C03
	pop af
	ldh [hROMBank], a
	ld [rROMB0], a
	ret
SfxB_FarStop::
	ldh a, [hROMBank]
	push af
	ld a, $7F
	ldh [hROMBank], a
	ld [rROMB0], a
	call $4C5C
	pop af
	ldh [hROMBank], a
	ld [rROMB0], a
	ret
